<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Confirm Package Checkout</title><style>*{box-sizing:border-box}body{margin:0;background:#eef3fb;color:#0c2f59;font-family:Arial,'Noto Sans Bengali',sans-serif}.wrap{max-width:760px;margin:24px auto;padding:16px}.card{background:#fff;border:1px solid #d5e4f7;border-radius:17px;padding:22px;margin-bottom:15px;box-shadow:0 8px 24px #123b6410}h1{font-size:26px;margin:15px 0}h2{font-size:21px}.row{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #e7eef6}.total{font-size:24px;font-weight:800;color:#076ac1}.message{background:#e8f4ff;border-radius:10px;padding:14px;line-height:1.75;margin-top:15px}.confirm{width:100%;border:none;background:#068756;color:white;font-size:17px;font-weight:bold;border-radius:10px;padding:16px;cursor:pointer}.back{color:#0866c4;text-decoration:none}.muted{font-size:13px;color:#60758d}@media(max-width:550px){.wrap{margin:0}.card{padding:15px}}</style></head><body><main class="wrap"><a class="back" href="{{ route('student.exam-section.package.review',$plan->id) }}">← পেমেন্ট পদ্ধতিতে ফিরুন</a><h1>পেমেন্ট নিশ্চিত করুন</h1><section class="card"><h2>{{ $plan->name }}</h2><div class="row"><span>প্যাকেজ মূল্য</span><strong class="total">৳{{ number_format((float)$plan->final_price,2) }}</strong></div><div class="row"><span>মেয়াদ</span><strong>{{ $plan->duration }} {{ $plan->duration_unit }}</strong></div><div class="row"><span>Payment Method</span><strong>{{ $method==='wallet'?'Referral Balance':'SSLCommerz' }}</strong></div>@if($method==='wallet')<div class="row"><span>Available Referral Balance</span><strong>৳{{ number_format($available,2) }}</strong></div><div class="row"><span>পেমেন্টের পর আনুমানিক Available Balance</span><strong>৳{{ number_format(max(0,$available-(float)$plan->final_price),2) }}</strong></div><div class="message">Confirm Payment চাপলে আপনার Referral Balance থেকে প্যাকেজের মূল্য কাটা হবে এবং সফল হলে Premium Access চালু হবে। SSLCommerz-এ যেতে হবে না।</div>@else<div class="message">Confirm Payment চাপলে SSLCommerz-এর নিরাপদ Payment Page খুলবে। যাচাইকৃত Payment সফল না হওয়া পর্যন্ত কোনো Premium Access চালু হবে না।</div>@endif</section><section class="card"><form action="{{ route('student.exam-section.package.checkout',$plan->id) }}" method="POST" id="paymentConfirm">@csrf<input type="hidden" name="method" value="{{ $method }}"><input type="hidden" name="checkout_token" value="{{ $token }}"><button type="submit" class="confirm" id="confirmButton">{{ $method==='wallet'?'Confirm Wallet Payment':'Proceed to SSLCommerz' }} →</button></form><p class="muted">একবারই Confirm করুন। পেমেন্ট চলাকালে Refresh বা বারবার Submit করবেন না।</p></section></main><script>document.getElementById('paymentConfirm').addEventListener('submit',function(){const b=document.getElementById('confirmButton');b.disabled=true;b.textContent='Processing…';});</script></body></html>